node - <<'JS'
const fs = require('fs');
const fail = [];
const ok = (cond, msg) => { if (!cond) fail.push(msg); };
const j = p => JSON.parse(fs.readFileSync(p, 'utf8'));

const answer = j('answer.json');
const names = ['north', 'south', 'east', 'west'];

// --- schema: exact top-level keys, no unrelated values ---
const topKeys = Object.keys(answer).sort();
ok(JSON.stringify(topKeys) === JSON.stringify(['grand_units','grand_weighted','regions']),
   'top-level keys wrong: ' + topKeys.join(','));
for (const k of ['grand_units','grand_weighted']) {
  ok(Number.isInteger(answer[k]) && answer[k] >= 0, k + ' not a non-negative integer: ' + answer[k]);
}

// --- schema: exactly the four regions, nothing else ---
const regionKeys = Object.keys(answer.regions).sort();
ok(JSON.stringify(regionKeys) === JSON.stringify(['east','north','south','west']),
   'region keys wrong/missing/extra: ' + regionKeys.join(','));
ok(Object.keys(answer.regions).length === 4, 'expected exactly 4 regions');

// --- recompute each region from its own original source ---
const recomputed = {};
for (const name of names) {
  const r = answer.regions[name];
  ok(r && typeof r === 'object', name + ': region entry missing');
  const ek = Object.keys(r).sort();
  ok(JSON.stringify(ek) === JSON.stringify(['count','units','weighted']),
     name + ': entry keys wrong: ' + ek.join(','));
  for (const f of ['count','units','weighted']) {
    ok(Number.isInteger(r[f]), name + '.' + f + ' not an integer: ' + r[f]);
  }

  const src = j(name + '.json');
  ok(Array.isArray(src), name + '.json is not a JSON array');
  // source completeness: every record counted, ids unique and complete
  ok(r.count === src.length, `${name}: count ${r.count} != source length ${src.length}`);
  const ids = src.map(o => o.id);
  ok(new Set(ids).size === ids.length, name + ': duplicate ids in source');
  ok(ids.every((v,i) => v === i + 1), name + ': ids not 1..n');
  ok(src.every(o => Number.isInteger(o.units) && Number.isInteger(o.weight)),
     name + ': non-integer units/weight in source');
  ok(src.every(o => Object.keys(o).sort().join(',') === 'id,units,weight'),
     name + ': unexpected fields in source records');

  const count = src.length;
  const units = src.reduce((a,o) => a + o.units, 0);
  const weighted = src.reduce((a,o) => a + o.units * o.weight, 0);
  recomputed[name] = { count, units, weighted };

  ok(r.count === count,    `${name}.count: answer ${r.count} != recomputed ${count}`);
  ok(r.units === units,    `${name}.units: answer ${r.units} != recomputed ${units}`);
  ok(r.weighted === weighted, `${name}.weighted: answer ${r.weighted} != recomputed ${weighted}`);
  console.log(`${name.padEnd(5)} answer ${JSON.stringify({count:r.count,units:r.units,weighted:r.weighted})} | source ${JSON.stringify(recomputed[name])} | MATCH`);
}

// --- grand totals from the recomputed regional values ---
const gu = names.reduce((a,n) => a + recomputed[n].units, 0);
const gw = names.reduce((a,n) => a + recomputed[n].weighted, 0);
const gt = names.reduce((a,n) => a + recomputed[n].count, 0);
ok(answer.grand_units === gu, `grand_units: answer ${answer.grand_units} != ${gu}`);
ok(answer.grand_weighted === gw, `grand_weighted: answer ${answer.grand_weighted} != ${gw}`);
const sumRegionsUnits = names.reduce((a,n) => a + answer.regions[n].units, 0);
const sumRegionsWeighted = names.reduce((a,n) => a + answer.regions[n].weighted, 0);
ok(answer.grand_units === sumRegionsUnits, 'grand_units != sum of answer regions');
ok(answer.grand_weighted === sumRegionsWeighted, 'grand_weighted != sum of answer regions');
console.log(`TOTALS answer grand_units ${answer.grand_units} == ${gu} | grand_weighted ${answer.grand_weighted} == ${gw} | records ${gt}`);

// --- fixture contents: sources are exactly the four files ---
const files = fs.readdirSync('.').sort();
console.log('fixture files: ' + files.join(', '));
for (const name of names) ok(files.includes(name + '.json'), 'missing source ' + name + '.json');

if (fail.length) {
  console.log('\nRESULT: FAIL');
  for (const f of fail) console.log('  - ' + f);
  process.exit(1);
}
console.log('\nRESULT: PASS — answer.json matches all four original sources');
